import sys,json,time,os
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
import numpy as np
from PIL import Image
class Painter:
 def __init__(self):
  self.r=Robot(); self.o=self.r.get_obs(cameras=[],video='none');self.pos=np.array(self.o.meta['proprio']['now'][7:10]);self.quat=np.array([0,1,0,0.]);self.buf=[];self.n=0
 def move(self,p,speed=.12,hold=0):
  p=np.array(p);n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/(speed*.05))))
  for a in np.linspace(0,1,n+1)[1:]:self.buf.append(np.r_[self.pos*(1-a)+p*a,self.quat].tolist())
  self.pos=p
  for _ in range(round(hold/.05)):self.buf.append(np.r_[p,self.quat].tolist())
 def flush(self):
  while self.buf:
   a=self.buf[:180];before=self.r.status()
   try:res=self.r.submit('ee_pose',a,dt=.05,cameras=[],video='none')
   except Exception:
    self.r.wait_ready();after=self.r.status()
    if after['control_steps']==before['control_steps']:continue
    if after['control_steps']!=before['control_steps']+len(a):raise
    res=None
   if res:
    self.o=res
    if res.meta.get('plan'):print('PLAN',res.meta['plan'],flush=True)
    if res.stopped:raise RuntimeError('partial execution')
   self.buf=self.buf[len(a):];self.n+=1
  return self.o
 def dip(self,c):
  self.move([*self.pos[:2],.07]);self.move([-.16+.03*(c%5),.14+.03*(c//5),.07]);self.move([-.16+.03*(c%5),.14+.03*(c//5),.025],hold=.25);self.move([*self.pos[:2],.07])
 def stroke_world(self,pts,depth):
  self.move([*self.pos[:2],.05]);self.move([*pts[0],.05]);self.move([*pts[0],.0202-depth],speed=.04,hold=.15)
  for p in pts[1:]:self.move([*p,.0202-depth],speed=.035)
  self.move([*pts[-1],.0202-depth],hold=.15);self.move([*pts[-1],.05],speed=.06)
 def park(self):
  self.move([*self.pos[:2],.10]);self.move([-.12,.23,.10]);self.flush()
 def photo(self,name,cameras=['canvas_cam']):
  o=self.r.get_obs(cameras=cameras);o.save('/app/output/'+name)
  for c,a in o.last.items():Image.fromarray(a).save('/app/output/'+name+'_'+c+'.png')
  print('STATUS',self.r.status(),flush=True);return o
